(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4343","module":"changshi","prompt":"我国宪法规定，全国人民代表大会代表应当同原选举单位和人民保持密切的联系，听取和反映人民的意见和要求，努力为人民服务，这是代表的？","options":["义务","待遇","职权","权利"],"answer":0,"explanation":"宪法规定，全国人民代表大会代表应当同原选举单位和人民保持密切的联系，听取和反映人民的意见和要求，努力为人民服务，这是代表的义务。","diff":1});
