(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4345","module":"changshi","prompt":"我国宪法规定，国家保护社会主义的公共财产，禁止任何组织或者个人用任何手段侵占或者？","options":["破坏国家的和集体的财产","使用公共财产","监督公共财产","管理公共财产"],"answer":0,"explanation":"宪法规定，社会主义的公共财产神圣不可侵犯；国家保护社会主义的公共财产，禁止任何组织或者个人用任何手段侵占或者破坏国家的和集体的财产。","diff":3});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4346","module":"changshi","prompt":"因债务人怠于行使其债权或者与该债权有关的从权利，影响债权人的到期债权实现的，债权人可以向人民法院请求以自己的名义代位行使债务人对相对人的权利，这被称为？","options":["代位权","撤销权","解除权","抗辩权"],"answer":0,"explanation":"民法规定，因债务人怠于行使其债权或者与该债权有关的从权利，影响债权人的到期债权实现的，债权人可以向人民法院请求以自己的名义代位行使债务人对相对人的权利，即代位权。","diff":3});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4347","module":"changshi","prompt":"债务人以放弃其债权、放弃债权担保、无偿转让财产等方式无偿处分财产权益，或者恶意延长其到期债权的履行期限，影响债权人的债权实现的，债权人可以请求人民法院？","options":["解除合同","宣告合同无效","撤销债务人的行为","变更合同"],"answer":2,"explanation":"民法规定，债务人以放弃其债权、放弃债权担保、无偿转让财产等方式无偿处分财产权益，影响债权人的债权实现的，债权人可以请求人民法院撤销债务人的行为，即撤销权。","diff":1});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4348","module":"changshi","prompt":"得利人没有法律根据取得不当利益的，受损失的人可以请求得利人？","options":["返还取得的利益","支付违约金","承担刑事责任","赔偿双倍损失"],"answer":0,"explanation":"民法规定，得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，即不当得利返还请求权。","diff":2});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4349","module":"changshi","prompt":"管理人没有法定的或者约定的义务，为避免他人利益受损失而管理他人事务的，可以请求受益人偿还因管理事务而支出的必要费用，这被称为？","options":["无因管理","不当得利","合同行为","侵权行为"],"answer":0,"explanation":"民法规定，管理人没有法定的或者约定的义务，为避免他人利益受损失而管理他人事务的，可以请求受益人偿还因管理事务而支出的必要费用，即无因管理。","diff":3});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4350","module":"changshi","prompt":"个人之间形成劳务关系，提供劳务一方因劳务造成他人损害的，由谁承担侵权责任？","options":["受害人自担","接受劳务一方承担侵权责任，接受劳务一方承担侵权责任后，可以向有故意或者重大过失的提供劳务一方追偿","双方共同承担","提供劳务一方承担"],"answer":1,"explanation":"民法典规定，个人之间形成劳务关系，提供劳务一方因劳务造成他人损害的，由接受劳务一方承担侵权责任；接受劳务一方承担侵权责任后，可以向有故意或者重大过失的提供劳务一方追偿。","diff":2});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4351","module":"changshi","prompt":"土地承包经营权自土地承包经营权合同生效时？","options":["交付时设立","设立","登记时设立","公告时设立"],"answer":1,"explanation":"民法典规定，土地承包经营权自土地承包经营权合同生效时设立；土地承包经营权的期限，耕地为30年，草地为30年至50年，林地为30年至70年。","diff":3});
