(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4353","module":"changshi","prompt":"地役权自地役权合同生效时设立，当事人要求登记的，可以向登记机构申请地役权登记，未经登记，不得对抗？","options":["合同相对人","善意第三人","所有人","使用人"],"answer":1,"explanation":"民法典规定，地役权自地役权合同生效时设立；当事人要求登记的，可以向登记机构申请地役权登记；未经登记，不得对抗善意第三人。","diff":2});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4354","module":"changshi","prompt":"抵押权人为债权人的，债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，债权人有权就该财产？","options":["直接占有","直接变卖","直接拍卖","优先受偿"],"answer":3,"explanation":"民法典规定，为担保债务的履行，债务人或者第三人不转移财产的占有，将该财产抵押给债权人的，债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，债权人有权就该财产优先受偿。","diff":1});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4355","module":"changshi","prompt":"企业、个体工商户、农业生产经营者可以将现有的以及将有的生产设备、原材料、半成品、产品抵押，这被称为？","options":["动产质押","最高额抵押","浮动抵押","固定抵押"],"answer":2,"explanation":"民法典规定，企业、个体工商户、农业生产经营者可以将现有的以及将有的生产设备、原材料、半成品、产品抵押，即浮动抵押；浮动抵押自抵押合同生效时设立，未经登记不得对抗善意第三人。","diff":1});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4356","module":"changshi","prompt":"为担保债务的履行，债务人或者第三人不转移财产的占有，将该财产质押给债权人的，这被称为？","options":["动产抵押","留置","权利质押","动产质押"],"answer":3,"explanation":"民法典规定，为担保债务的履行，债务人或者第三人将其动产出质给债权人占有的，债务人不履行到期债务或者发生当事人约定的实现质权的情形，债权人有权就该动产优先受偿，即动产质押。","diff":2});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4357","module":"changshi","prompt":"留置权成立的条件不包括？","options":["债权人合法占有债务人的动产","债务已届清偿期","债权与动产的占有属于同一法律关系","债权人任意占有债务人的财产"],"answer":3,"explanation":"留置权的成立条件包括债权人合法占有债务人的动产、债务已届清偿期、债权与动产的占有属于同一法律关系（企业之间留置除外）；债权人任意占有债务人的财产不能成立留置权。","diff":3});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4358","module":"changshi","prompt":"最高额抵押权是为担保债务的履行，债务人或者第三人对一定期间内将要连续发生的债权提供担保财产的，债务人不履行到期债务或者发生当事人约定的实现抵押权的情形的，抵押权人有权在？","options":["任意范围内受偿","全部债权范围内受偿","最低债权额内受偿","最高债权额限度内就该担保财产优先受偿"],"answer":3,"explanation":"民法典规定，最高额抵押权是债务人对一定期间内将要连续发生的债权提供担保财产，债务人不履行到期债务的，抵押权人有权在最高债权额限度内就该担保财产优先受偿。","diff":3});
