(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4547","module":"changshi","prompt":"合伙合同是两个以上合伙人为了共同的事业目的，订立的共享利益、共担风险的合同，合伙人对合伙债务承担？","options":["补充责任","按份责任","有限责任","连带责任"],"answer":3,"explanation":"民法规定，合伙人对合伙债务承担连带责任；清偿合伙债务超过自己应当承担份额的合伙人，有权向其他合伙人追偿。","diff":2});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4548","module":"changshi","prompt":"无民事行为能力人在幼儿园、学校或者其他教育机构学习、生活期间受到人身损害的，幼儿园、学校或者其他教育机构应当承担侵权责任，但是能够证明尽到教育、管理职责的，？","options":["不承担侵权责任","承担全部责任","承担一半责任","承担补偿责任"],"answer":0,"explanation":"民法典规定，无民事行为能力人在幼儿园、学校或者其他教育机构学习、生活期间受到人身损害的，幼儿园、学校或者其他教育机构应当承担侵权责任；但是能够证明尽到教育、管理职责的，不承担侵权责任，即过错推定责任。","diff":3});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4549","module":"changshi","prompt":"限制民事行为能力人在学校或者其他教育机构学习、生活期间受到人身损害，学校或者其他教育机构未尽到教育、管理职责的，应当？","options":["承担刑事责任","承担侵权责任","承担全部责任","不承担责任"],"answer":1,"explanation":"民法典规定，限制民事行为能力人在学校或者其他教育机构学习、生活期间受到人身损害，学校或者其他教育机构未尽到教育、管理职责的，应当承担侵权责任，即过错责任。","diff":3});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4550","module":"changshi","prompt":"为他人无偿提供劳务的帮工人，在从事帮工活动中致人损害的，被帮工人应当承担赔偿责任；被帮工人明确拒绝帮工的，？","options":["不承担赔偿责任","承担补偿责任","承担全部责任","承担一半责任"],"answer":0,"explanation":"民法规定，为他人无偿提供劳务的帮工人，在从事帮工活动中致人损害的，被帮工人应当承担赔偿责任；被帮工人明确拒绝帮工的，不承担赔偿责任；但是可以在受益范围内予以适当补偿。","diff":2});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4551","module":"changshi","prompt":"自然人享有姓名权，有权依法决定、使用、变更或者许可他人使用自己的姓名，但是不得？","options":["使用自己的姓名","变更自己的姓名","许可他人使用","违背公序良俗"],"answer":3,"explanation":"民法规定，自然人享有姓名权，有权依法决定、使用、变更或者许可他人使用自己的姓名，但是不得违背公序良俗；任何组织或者个人不得以干涉、盗用、假冒等方式侵害他人的姓名权。","diff":3});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4552","module":"changshi","prompt":"自然人享有肖像权，有权依法制作、使用、公开或者许可他人使用自己的肖像，未经肖像权人同意，不得制作、使用、公开肖像权人的肖像，但是法律另有规定的除外，这体现了肖像权的？","options":["专属性","开放性","共享性","公共性"],"answer":0,"explanation":"民法规定，自然人享有肖像权，未经肖像权人同意，不得制作、使用、公开肖像权人的肖像，但是法律另有规定的除外，体现了肖像权的专属性；合理使用情形包括个人学习、新闻报道、国家机关执行职务等。","diff":1});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4553","module":"changshi","prompt":"民事主体享有名誉权，任何组织或者个人不得以侮辱、诽谤等方式侵害他人的名誉权，名誉是对民事主体的？","options":["政治立场的评价","财产状况的评价","品德、声望、才能、信用等的社会评价","宗教信仰的评价"],"answer":2,"explanation":"民法规定，名誉是对民事主体的品德、声望、才能、信用等的社会评价；任何组织或者个人不得以侮辱、诽谤等方式侵害他人的名誉权。","diff":2});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4554","module":"changshi","prompt":"民事主体享有荣誉权，任何组织或者个人不得非法剥夺他人的荣誉称号，不得诋毁、贬损他人的？","options":["荣誉","姓名","肖像","名誉"],"answer":0,"explanation":"民法规定，民事主体享有荣誉权，任何组织或者个人不得非法剥夺他人的荣誉称号，不得诋毁、贬损他人的荣誉；获得的荣誉称号应当记载而没有记载的，民事主体可以请求记载。","diff":2});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4555","module":"changshi","prompt":"夫妻共同债务的清偿，离婚时，原为夫妻共同生活所负的债务，应当共同偿还，共同财产不足清偿的，或者财产归各自所有的，由双方？","options":["各自清偿","协议清偿，协议不成的，由人民法院判决","由债权人决定","由一方清偿"],"answer":1,"explanation":"民法典规定，离婚时，原为夫妻共同生活所负的债务，应当共同偿还；共同财产不足清偿的，或者财产归各自所有的，由双方协议清偿，协议不成的，由人民法院判决。","diff":1});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4556","module":"changshi","prompt":"离婚时，夫妻的共同财产由双方协议处理，协议不成的，由人民法院根据财产的具体情况，按照照顾子女、女方和无过错方权益的原则？","options":["公证","调解","仲裁","判决"],"answer":3,"explanation":"民法典规定，离婚时，夫妻的共同财产由双方协议处理；协议不成的，由人民法院根据财产的具体情况，按照照顾子女、女方和无过错方权益的原则判决。","diff":1});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4557","module":"changshi","prompt":"离婚后，不满2周岁的子女，以由母亲直接抚养为原则；已满2周岁的，父母双方对抚养问题协议不成的，由人民法院根据双方的具体情况，按照？","options":["经济条件判决","最有利于未成年子女的原则判决","年龄大小判决","父母意愿判决"],"answer":1,"explanation":"民法典规定，离婚后，不满2周岁的子女，以由母亲直接抚养为原则；已满2周岁的，父母双方对抚养问题协议不成的，由人民法院根据双方的具体情况，按照最有利于未成年子女的原则判决；子女已满8周岁的，应当尊重其真实意愿。","diff":2});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4558","module":"changshi","prompt":"有负担能力的祖父母、外祖父母，对于父母已经死亡或者父母无力抚养的未成年孙子女、外孙子女，有？","options":["探望的权利","监护的权利","收养的权利","抚养的义务"],"answer":3,"explanation":"民法典规定，有负担能力的祖父母、外祖父母，对于父母已经死亡或者父母无力抚养的未成年孙子女、外孙子女，有抚养的义务；有负担能力的孙子女、外孙子女，对于子女已经死亡或者子女无力赡养的祖父母、外祖父母，有赡养的义务。","diff":2});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4559","module":"changshi","prompt":"抢夺公私财物，数额较大的，或者多次抢夺的，构成？","options":["抢劫罪","抢夺罪","诈骗罪","盗窃罪"],"answer":1,"explanation":"抢夺罪是抢夺公私财物，数额较大，或者多次抢夺的行为；抢夺罪与抢劫罪的区别在于是否使用暴力、胁迫方法。","diff":2});
