(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4561","module":"changshi","prompt":"故意毁坏公私财物，数额较大或者有其他严重情节的，构成？","options":["破坏生产经营罪","抢劫罪","盗窃罪","故意毁坏财物罪"],"answer":3,"explanation":"故意毁坏财物罪是故意毁坏公私财物，数额较大或者有其他严重情节的行为；故意毁坏财物罪侵犯的是财产权，不以非法占有为目的。","diff":2});
