(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4565","module":"changshi","prompt":"开设赌场或者以营利为目的聚众赌博、以赌博为业的，构成？","options":["非法经营罪","开设赌场罪或赌博罪","盗窃罪","诈骗罪"],"answer":1,"explanation":"开设赌场罪是开设赌场的行为；赌博罪是以营利为目的，聚众赌博或者以赌博为业的行为；开设赌场罪的处罚重于赌博罪。","diff":1});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4566","module":"changshi","prompt":"组织他人卖淫或者强迫他人卖淫的，构成？","options":["引诱幼女卖淫罪","组织卖淫罪或强迫卖淫罪","传播性病罪","容留卖淫罪"],"answer":1,"explanation":"组织卖淫罪是组织他人卖淫的行为；强迫卖淫罪是强迫他人卖淫的行为；两者都是严重犯罪，处5年以上10年以下有期徒刑，并处罚金。","diff":2});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4567","module":"changshi","prompt":"明知自己患有梅毒、淋病等严重性病而卖淫、嫖娼的，构成？","options":["传播性病罪","容留卖淫罪","故意伤害罪","组织卖淫罪"],"answer":0,"explanation":"传播性病罪是明知自己患有梅毒、淋病等严重性病而卖淫、嫖娼的行为；该罪侵犯的是公共卫生秩序和他人身体健康。","diff":3});
