(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4569","module":"changshi","prompt":"我国刑法规定，被判处死刑缓期执行的犯罪分子，在死刑缓期执行期间，如果没有故意犯罪，2年期满以后，减为？","options":["有期徒刑15年","无期徒刑","有期徒刑20年","有期徒刑25年"],"answer":1,"explanation":"刑法规定，被判处死刑缓期执行的犯罪分子，在死刑缓期执行期间，如果没有故意犯罪，2年期满以后，减为无期徒刑；如果确有重大立功表现，2年期满以后，减为25年有期徒刑。","diff":1});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4570","module":"changshi","prompt":"我国刑法规定，被判处死刑缓期执行的犯罪分子，在死刑缓期执行期间，如果故意犯罪，情节恶劣的，报请最高人民法院核准后？","options":["减为有期徒刑","假释","减为无期徒刑","执行死刑"],"answer":3,"explanation":"刑法规定，被判处死刑缓期执行的犯罪分子，在死刑缓期执行期间，如果故意犯罪，情节恶劣的，报请最高人民法院核准后执行死刑；对于故意犯罪未执行死刑的，死刑缓期执行的期间重新计算。","diff":3});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4571","module":"changshi","prompt":"我国刑法规定，对于被判处拘役的犯罪分子，由公安机关就近执行，每月可以回家？","options":["5至7天","7至10天","3至5天","1至2天"],"answer":3,"explanation":"刑法规定，对于被判处拘役的犯罪分子，由公安机关就近执行；在执行期间，被判处拘役的犯罪分子每月可以回家1至2天；参加劳动的，可以酌量发给报酬。","diff":3});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({"id":"cs-4572","module":"changshi","prompt":"我国刑法规定，对于被判处管制的犯罪分子，在执行期间，应当遵守的规定不包括？","options":["遵守法律、行政法规，服从监督","离开所居住的市、县或者迁居，应当报经执行机关批准","未经执行机关批准，不得行使言论、出版、集会、结社、游行、示威自由的权利","可以自由出入任何场所"],"answer":3,"explanation":"刑法规定，被判处管制的犯罪分子应当遵守法律、行政法规，服从监督，未经执行机关批准不得行使言论出版集会结社游行示威自由的权利，离开所居住的市县或者迁居应当报经执行机关批准等；不得自由出入任何场所。","diff":2});
